"""Readable paired flask retrieval results and lexical shared-prefix observations."""
from pathlib import Path
from html import escape
import hashlib,json,math,shutil,importlib.util
HERE=Path(__file__).resolve().parent;OUT=HERE.parents[1]/'results/2026-11-12-flask-binding'
s=json.loads((OUT/'analysis.json').read_text());r=json.loads((OUT/'results.json').read_text());spec=importlib.util.spec_from_file_location('audit',HERE/'analyze.py');audit=importlib.util.module_from_spec(spec);spec.loader.exec_module(audit)
bind=[c for c in s['cases'] if c['kind']=='binding'];lex=[c for c in s['cases'] if c['kind']=='lexical_observation'];rows=[x for x in s['rows'] if x['kind']=='binding'];assert len(bind)==8 and s['binding_native_correct']==8 and s['binding_off_correct']==8 and all(x['edited_input_tokens']==1 for x in rows)
scale=max(.5,math.ceil(max(t['natural_gate'] for c in r['cases'] for t in c['zero']['trace'] if t['context']=='generation')*2)/2)
def pct(x):
 if x is None:return '—'
 return (format(100*x,'.2e') if 0<100*x<.001 else format(100*x,'.4f'))+'%'
def trace(v,phase):return [t for t in v['trace'] if t['context']=='generation' and t['phase']==phase]
def heat(tr,removed=set(),after=False):
 out=[]
 for t in tr:
  edited=t['phase']=='input' and t['position'] in removed;g=0 if edited and after else t['natural_gate'];a=min(.88,.2+.68*g/scale) if g>0 else 0;word=escape(t['token']).replace('\n','↵\n').replace(' ','·');title=f"Token {t['position']}; ID {t['token_id']}; {t['phase']}; raw {t['raw']:.6f}; natural gate {t['natural_gate']:.6f}; displayed gate {g:.6f}; {'removed' if edited else 'unedited'}"
  out.append(f"<span class='token {'edited' if edited else ''}' style='background:rgba(229,113,72,{a})' title='{escape(title,quote=True)}'>{word}</span>")
 return ''.join(out)
summary=[]
for x in rows:
 c=next(c for c in bind if c['id']==x['id']);summary.append(f"<tr><td><a href='#{c['pair_id']}'>{c['pair_id']}</a></td><td>{c['query_owner']}</td><td>{c['water_owner']}</td><td>{x['native_response']} → {x['off_response']}</td><td>{pct(x['native_p_water'])} → {pct(x['off_p_water'])}</td><td>{pct(x['native_p_oil'])} → {pct(x['off_p_oil'])}</td><td>{x['delta_log_water_over_oil']:+.4f}</td></tr>")
def case_panel(c):
 raw=next(x for x in r['cases'] if x['id']==c['id']);v=raw['runs'][0];x=next(x for x in rows if x['id']==c['id']);removed=set(x['edited_positions']);positions=', '.join(f"{t['position']}: {t['token']!r}, gate {t['gate']:.6f}" for t in c['input_positive'])
 return f'''<div class="query-case" data-case="{c['id']}"><p class="query">{escape(c['prompt'])}</p><p class="legend">Active input: {escape(positions)}. Every supplied input position is eligible for removal; this is the one positive contribution. No generated tokens edited.</p><h4>Native input · activation heatmap</h4><div class="tokens input-tokens">{heat(trace(raw['zero'],'input'),removed)}</div><details><summary>Input after removal</summary><div class="tokens input-tokens">{heat(trace(raw['zero'],'input'),removed,True)}</div></details><div class="answers"><div class="answer"><h4>Native response</h4><div class="response native-response">{escape(c['native_response'])}</div><div class="tokens">{heat(trace(raw['zero'],'response'))}</div></div><div class="answer"><h4>T2375 off · all input</h4><div class="response off-response">{escape(x['off_response'])}</div><p class="status-note">{x['edited_input_tokens']} positive input contribution removed · {x['off_stop']}</p><div class="tokens">{heat(trace(v,'response'))}</div></div></div><div class="scroll"><table><thead><tr><th>Exact word prefix</th><th>Native</th><th>All-input off</th></tr></thead><tbody><tr><td>water</td><td>{pct(x['native_p_water'])}</td><td>{pct(x['off_p_water'])}</td></tr><tr><td>oil</td><td>{pct(x['native_p_oil'])}</td><td>{pct(x['off_p_oil'])}</td></tr></tbody></table></div><p class="status-note">Delta ln(P(water)/P(oil)): {x['delta_log_water_over_oil']:+.6f}. Expected-word probability change: {x['delta_expected_percentage_points']:+.6f} percentage points.</p><details><summary>Exact formatted prompt and word-plus-EOS scores</summary><pre class="tokens">{escape(raw['case']['formatted_prompt'])}</pre><p>Expected word + EOS: {pct(x['native_p_expected_eos'])} → {pct(x['off_p_expected_eos'])}. Prefix scores above exclude punctuation/EOS; the actual responses end with a period.</p></details></div>'''
cards=[]
for layout in dict.fromkeys(c['pair_id'] for c in bind):
 pair=[c for c in bind if c['pair_id']==layout];dax=next(c for c in pair if c['query_owner']=='Dax');neri=next(c for c in pair if c['query_owner']=='Neri');cards.append(f'''<article class="card" id="{layout}"><div class="card-head"><h3>{layout}</h3><span class="badge">Both native answers correct · both off answers correct</span></div><p>Dax → <strong>{dax['assignment']['Dax']}</strong> · Neri → <strong>{dax['assignment']['Neri']}</strong>. Fact order: {' then '.join(dax['fact_order'])}.</p>{case_panel(dax)}<details class="paired-control"><summary>Neri control: {neri['native_response']} → {neri['native_response']} · inspect full prompt and comparison</summary>{case_panel(neri)}</details></article>''')
lexrows=[];lexdetails=[]
for c in lex:
 raw=next(x for x in r['cases'] if x['id']==c['id']);pieces=' + '.join(f"<code>{escape(repr(t['token']))}</code> [ID {t['token_id']}, gate {t['gate']:.6f}]" for t in c['probe_word_tokens']);active='; '.join(f"{t['token']!r} at response index {t['response_index']}: {t['gate']:.6f}" for t in c['response_positive']) or 'none'
 lexrows.append(f"<tr><td>{escape(c['probe_word'])}</td><td>{pieces}</td><td>{escape(c['native_response'])}<br><small>{'copy criterion passes' if c['native_correct'] else 'copy criterion fails: repeated word'}</small></td><td>{escape(active)}</td></tr>")
 lexdetails.append(f"<details><summary>{escape(c['probe_word'])}: full prompt and native activation</summary><p class='query'>{escape(c['prompt'])}</p><div class='tokens input-tokens'>{heat(trace(raw['zero'],'input'))}</div><p>Native response:</p><div class='tokens'>{heat(trace(raw['zero'],'response'))}</div></details>")
cal=next(c for c in r['cases'] if c['id']=='month-calibration-11');off=cal['runs'][0];calrows=''.join(f"<tr><td>{w}</td><td>{pct(audit.aggregate(cal['native'],w)['probability'])}</td><td>{pct(audit.aggregate(off,w)['probability'])}</td></tr>" for w in ['November','December']);maxpp=max(abs(x['delta_expected_percentage_points']) for x in rows)
version=hashlib.sha256((OUT/'analysis.json').read_bytes()+(HERE/'render.py').read_bytes()).hexdigest()[:12]
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="only light"><meta name="darkreader-lock"><title>T2375: water/oil flask binding and Waterloo</title><link rel="stylesheet" href="style.css?v={version}"></head><body><main><nav><a href="../2026-11-12-water-ice-probe/">← Water/ice probe</a><span>Native Qwen3-4B · L29–T2375 · 12 November 2026</span></nav><header><p class="eyebrow">Arbitrary facts · paired native controls · all-input contribution removal</p><h1>Can it still remember<br>which flask holds water?</h1><p class="finding"><strong>Yes in all eight tested questions.</strong> Both names are answered correctly before and after removing T2375 at every supplied input position. Each binding case has one positive input contribution, on <code> water</code>, which is actually removed. Small probability changes remain; the largest expected-word change is {maxpp:.4f} percentage points.</p><p>Four fixed layouts counterbalance water/oil assignment between Dax and Neri and reverse the fact order. We ask both names, freeze all native and zero/observer checks before edits, and preserve every supplied word. Separate word-copying observations inspect water, watermelon and Waterloo tokenization; they are not causal tests.</p><div class="metrics"><div><strong>8 / 8</strong><span>native flask answers correct</span></div><div><strong>8 / 8</strong><span>all-input off answers correct</span></div><div><strong>8 / 8</strong><span>have a positive contribution removed</span></div><div><strong>0</strong><span>generated tokens edited</span></div></div></header><section><h2>Every flask answer and probability</h2><div class="scroll"><table><thead><tr><th>Layout</th><th>Ask about</th><th>Water owner</th><th>Native → off</th><th>P(water), native → off</th><th>P(oil), native → off</th><th>Delta ln(P(water)/P(oil))</th></tr></thead><tbody>{''.join(summary)}</tbody></table></div><p class="muted">Probabilities sum four prescribed disjoint complete word-token prefixes: lowercase/titlecase, with zero/one leading space. They exclude punctuation/EOS, other tokenizations and longer answer phrases. These are prefix events, not universal semantic probabilities. Word-plus-EOS is separate. The log-ratio comparison exposes changes despite high native confidence; positive deltas favor water over oil, negative deltas favor oil. Percentages are rounded; tiny raw FP32 numerical sums above one are retained in the raw data.</p></section><section id="flask-prompts"><h2>Exact prompts, activation and removal</h2><p class="legend">Orange marks a positive natural gate; blue outlines mark the contribution removed at that input token. All heatmaps share a 0–{scale:.2f} scale. Hover for token ID, position, raw encoder value and gate. Dax comparisons are expanded; each paired Neri comparison opens below it. Response gates are observed but unedited.</p>{''.join(cards)}</section><section id="lexical"><h2>Waterloo: the word piece matters</h2><p>Shared carrier: <code>The word is WORD. Repeat that word, and nothing else.</code> These four cases are <strong>observation-only</strong>; no lexical ablations were run. Two native copying responses repeat the word twice and fail the copy criterion; those outputs are retained.</p><div class="scroll"><table><thead><tr><th>Inserted word</th><th>Input word pieces and gates</th><th>Native response</th><th>Active generated pieces</th></tr></thead><tbody>{''.join(lexrows)}</tbody></table></div><p><strong>The identical activation is expected from the shared causal prefix.</strong> Lowercase water, watermelon and waterloo all have exactly the same input-token history through <code> water</code> (ID 3015), with gate <strong>{s['shared_prefix_check']['shared_gate']:.6f}</strong>. At this input position the model has not yet seen <code>melon</code> or <code>loo</code>. This equality does not show that the completed words have the same liquid-water meaning.</p><p>Uppercase <code> Waterloo</code> is one input token (76375) and is inactive in this carrier. Its generated answer instead splits into <code>Water</code> + <code>loo</code>, and the generated Water piece activates. Tokenization and context both matter; these observations do not identify the full operator’s function or establish a universal spelling rule.</p>{''.join(lexdetails)}<p><a href="lexical-prefix-check.json">Verified shared-prefix token IDs and equality check</a></p></section><section><h2>Calibration: the original month shift still works</h2><p><code>the eleventh month of the year is</code> starts with November natively and December after all-input removal. Only final <code> is</code> has a positive gate in that prompt. Full 32-token continuations are retained and are not claimed to be coherent beyond the initial answer.</p><div class="scroll"><table><thead><tr><th>Literal month prefix</th><th>Native</th><th>T2375 off</th></tr></thead><tbody>{calrows}</tbody></table></div></section><section><h2>What this says about water-related function</h2><p>T2375 removal does not break these simple two-flask bindings. That does not prove that the transform has no water-related role in other contexts, or that other pathways are not compensating. The word-copying observations reveal a tokenization/shared-prefix issue: activation on a water piece inside a longer word cannot by itself be labelled as recognizing the completed word’s meaning.</p><details><summary>Scope, verification and limitations</summary><p>Native BF16 Qwen3-4B, pinned model/MOLT weights, greedy, chat thinking off, eager attention, TF32 disabled, max 32 generated tokens. Observe the post-attention L29 residual before native RMSNorm, apply checkpoint input standardization, calculate the natural JumpReLU gate and low-rank operator in native output units, and subtract <code>gate × operator</code> from the native MLP output in FP32 followed by one BF16 cast. Every supplied input position is selected. All later native computation remains; no generated/candidate positions are edited and no full MLP is replaced.</p><p>Four paired native layouts pass before any nonzero edit. All native/zero outputs and scored probabilities match exactly. Baseline eligibility is hash-locked before ablations. The independent CPU audit verifies gates/operators, all selected masks, actual positive edits, word probabilities and exact BF16 rounding at {s['audit']['independent_vector_samples']} saved vector positions. Eight binding contributions plus one month-calibration contribution are removed. The four lexical cases are native/observer only.</p><p>Limitations: eight easy, highly confident binding answers; only two owners and two liquids; no unrelated norm-matched active-transform control; two lexical-copying failures; no causal intervention in lexical cases. Small probability effects do not identify a mechanism. All source, source hashes, failed copying outputs and exact token scores are retained.</p></details><p class="source-links"><a href="probabilities.csv">All response/probability rows</a><a href="analysis.json">Independent audit and observations</a><a href="protocol.json">Frozen cases</a><a href="baseline-lock.json">Baseline lock</a><a href="results.json">Full captures</a><a href="source/run.py">Inference source</a><a href="source/analyze.py">Audit source</a></p></section><footer>Flask removals are causal input interventions; lexical cases are observations. Layer and token IDs are zero-based.</footer></main></body></html>'''
(OUT/'index.html').write_text(html);(OUT/'style.css').write_text((HERE.parent/'month-codewords-20261112/web/style.css').read_text()+'\n.query{white-space:pre-wrap}\n');(OUT/'source').mkdir(exist_ok=True)
